#!/bin/sh
# Generated by tools/gemm_remote_leg.sh (--payload mamba). RUNS ON THE POD.
set -u
campaign_started=$(date +%s)
ROOT=/root/mojolearn
OUT=/root/gemm_leg_out
mkdir -p "$OUT"
cd "$ROOT" || exit 9
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 NUMEXPR_NUM_THREADS=1
export MAX_JOBS=4 CMAKE_BUILD_PARALLEL_LEVEL=4
cores=$(python3 -c 'import os; print(",".join(map(str, sorted(os.sched_getaffinity(0))[:4])))')
taskset -pc "$cores" $$ > "$OUT/cpu-affinity.log" 2>&1 || exit 9
{
  echo "vendor=nvidia"
  echo "payload=mamba"
  echo "knn_layout_only=1"
  echo "commit=323b7301a832c831cabfaaf71e014fdffb3ba26f"
  echo "started=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
} > "$OUT/leg.txt"
uname -a > "$OUT/uname.txt" 2>&1
nvidia-smi --query-gpu=name,driver_version --format=csv,noheader > "$OUT/gpu.txt" 2>&1 || echo "no vendor smi tool answered" >> "$OUT/gpu.txt"
{ find . -name '*.mojo' -not -path './.pixi/*' -not -path './bench/results/*' \
    | LC_ALL=C sort | xargs shasum -a 256 2>/dev/null || \
  find . -name '*.mojo' -not -path './.pixi/*' -not -path './bench/results/*' \
    | LC_ALL=C sort | xargs sha256sum ; } \
  | { shasum -a 256 2>/dev/null || sha256sum ; } \
  | awk '{print $1}' > "$OUT/source_sha256.txt"
if [ ! -x "$HOME/.pixi/bin/pixi" ] && ! command -v pixi >/dev/null 2>&1; then
  if [ "0" = 1 ] || [ "1" = 1 ]; then
    timeout -k 10 120 sh -c 'curl -fsSL --max-time 30 https://pixi.sh/install.sh | sh' > "$OUT/pixi_install.log" 2>&1
  else
    curl -fsSL https://pixi.sh/install.sh | sh > "$OUT/pixi_install.log" 2>&1
  fi
fi
PATH="$HOME/.pixi/bin:$PATH"
export PATH
if [ "0" = 1 ] || [ "1" = 1 ]; then
    timeout -k 10 600 pixi install > "$OUT/pixi_env.log" 2>&1
else
pixi install > "$OUT/pixi_env.log" 2>&1
fi
echo "pixi_install_exit=$?" >> "$OUT/leg.txt"
# Layout-only reuses transport/bootstrap, not the Mamba/UMAP workload.
if [ "1" = 1 ]; then
    layout_rc=124
    work_remaining=$((1500 - $(date +%s) + campaign_started))
    if ! command -v timeout >/dev/null 2>&1; then
        layout_rc=127
        echo "timeout is required" > "$OUT/layout-console.log"
    elif [ "$work_remaining" -gt 0 ]; then
        MOJOLEARN_LAYOUT_PRICE_OUT="$OUT/layout-price" \
          timeout -k 30 "$work_remaining" bash tools/knn_layout_dispatch_price.sh \
          > "$OUT/layout-console.log" 2>&1
        layout_rc=$?
    else
        echo "shared work deadline expired" > "$OUT/layout-console.log"
    fi
    echo "layout_exit=$layout_rc" >> "$OUT/leg.txt"
    echo "finished=$(date -u +%Y-%m-%dT%H:%M:%SZ)" >> "$OUT/leg.txt"
    tail -40 "$OUT/layout-console.log"
    : > /root/gemm_leg.done
    echo REMOTE_BODY_DONE
    exit "$layout_rc"
fi
# Both witnesses share one work deadline, preserving the fetch reserve.
# Refuse without timeout instead of silently running an unbounded payload.
work_started=$(date +%s)
if [ "0" = 1 ]; then work_started=$campaign_started; fi
if ! command -v timeout >/dev/null 2>&1; then
    echo "umap_identity_exit=127" >> "$OUT/leg.txt"
    echo "timeout is required for the guarded payload" > "$OUT/mamba_cert_console.log"
    cert_rc=127
else
    timeout -k 30 180 pixi run mojo run -D MOJOLEARN_NUMERIC_IDENTICAL=1 \
      -I . umap/checks/identity_check.mojo > "$OUT/umap.identity.log" 2>&1
    echo "umap_identity_exit=$?" >> "$OUT/leg.txt"
    work_remaining=$((1500 - $(date +%s) + work_started))
    if [ "$work_remaining" -gt 0 ]; then
        MOJOLEARN_COMMIT="323b7301a832c831cabfaaf71e014fdffb3ba26f" MOJOLEARN_MAMBA_CERT_OUT="$OUT/mamba-cert" \
          MOJOLEARN_MAMBA_CERT_VENDOR="nvidia" \
          timeout -k 30 "$work_remaining" pixi run mamba-backward-cert-nvidia \
          > "$OUT/mamba_cert_console.log" 2>&1
        cert_rc=$?
    else
        echo "shared work deadline expired" > "$OUT/mamba_cert_console.log"
        cert_rc=124
    fi
fi
echo "mamba_cert_exit=$cert_rc" >> "$OUT/leg.txt"
work_remaining=$((1500 - $(date +%s) + work_started))
followup_rc=124
if [ "$work_remaining" -gt 60 ]; then
  if [ "0" = 1 ]; then
    MOJOLEARN_CAMPAIGN_OUT="$OUT/campaign" MOJOLEARN_COMMIT="323b7301a832c831cabfaaf71e014fdffb3ba26f" \
      MOJOLEARN_CAMPAIGN_SECONDS="$work_remaining" \
      timeout -k 30 "$work_remaining" bash tools/nvidia_campaign.sh \
      > "$OUT/campaign-console.log" 2>&1
    followup_rc=$?
  else
    MOJOLEARN_FOLLOWUP_OUT="$OUT/followup" MOJOLEARN_MAMBA_CERT_VENDOR="nvidia" \
      timeout -k 30 "$work_remaining" bash tools/umap_mamba_followup.sh \
      > "$OUT/followup-console.log" 2>&1
    followup_rc=$?
  fi
fi
echo "followup_exit=$followup_rc" >> "$OUT/leg.txt"
echo "finished=$(date -u +%Y-%m-%dT%H:%M:%SZ)" >> "$OUT/leg.txt"
tail -40 "$OUT/mamba_cert_console.log"
: > /root/gemm_leg.done
echo REMOTE_BODY_DONE
